-- SQL*Plus, personal test schema only. Review 00_check_oracle.sql first.
-- Renames ONLY colliding constraint/index names belonging to the five preserved tables.
-- Does not rename tables or delete data. DDL commits implicitly. Refuses partial new tables.
WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK
SET SQLBLANKLINES ON
SET DEFINE OFF
DECLARE
 n NUMBER;
BEGIN
 SELECT COUNT(*) INTO n FROM user_tables WHERE table_name IN ('MEMBER','LANE','RESERVATION','RESERVATION_LANE','USAGE');
 IF n<>0 THEN RAISE_APPLICATION_ERROR(-20010,'Canonical tables exist: stop and inspect'); END IF;
 SELECT COUNT(*) INTO n FROM user_tables WHERE table_name IN ('BAK_V15_MEMBER','BAK_V15_LANE','BAK_V15_RESERVATION','BAK_V15_RESERVATION_LANE','BAK_V15_USAGE');
 IF n<>5 THEN RAISE_APPLICATION_ERROR(-20011,'Five preserved tables required'); END IF;
 FOR r IN (SELECT table_name,constraint_name FROM user_constraints WHERE table_name IN ('BAK_V15_MEMBER','BAK_V15_LANE','BAK_V15_RESERVATION','BAK_V15_RESERVATION_LANE','BAK_V15_USAGE') AND constraint_name IN ('PK_MEMBER','UK_MEMBER_LOGIN_ID','UK_MEMBER_PHONE','CK_MEMBER_ROLE','CK_MEMBER_STATUS','CK_MEMBER_NO_SHOW','PK_LANE','UK_LANE_NUMBER','CK_LANE_NUMBER','CK_LANE_STATUS','PK_RESERVATION','FK_RESERVATION_MEMBER','CK_RESERVATION_TIME','CK_RESERVATION_PERSON','CK_RESERVATION_ACTUAL','CK_RESERVATION_STATUS','CK_RESERVATION_CANCEL','PK_RESERVATION_LANE','FK_RL_RESERVATION','FK_RL_LANE','UK_RL_RES_LANE','CK_RL_USAGE_STATUS','PK_USAGE','FK_USAGE_RL','UK_USAGE_RL','CK_USAGE_TIME')) LOOP
  EXECUTE IMMEDIATE 'ALTER TABLE '||DBMS_ASSERT.ENQUOTE_NAME(r.table_name)||' RENAME CONSTRAINT '||DBMS_ASSERT.ENQUOTE_NAME(r.constraint_name)||' TO '||DBMS_ASSERT.ENQUOTE_NAME('OLD_'||r.constraint_name);
 END LOOP;
 FOR r IN (SELECT index_name FROM user_indexes WHERE table_name IN ('BAK_V15_MEMBER','BAK_V15_LANE','BAK_V15_RESERVATION','BAK_V15_RESERVATION_LANE','BAK_V15_USAGE') AND index_name IN ('PK_MEMBER','UK_MEMBER_LOGIN_ID','UK_MEMBER_PHONE','CK_MEMBER_ROLE','CK_MEMBER_STATUS','CK_MEMBER_NO_SHOW','PK_LANE','UK_LANE_NUMBER','CK_LANE_NUMBER','CK_LANE_STATUS','PK_RESERVATION','FK_RESERVATION_MEMBER','CK_RESERVATION_TIME','CK_RESERVATION_PERSON','CK_RESERVATION_ACTUAL','CK_RESERVATION_STATUS','CK_RESERVATION_CANCEL','PK_RESERVATION_LANE','FK_RL_RESERVATION','FK_RL_LANE','UK_RL_RES_LANE','CK_RL_USAGE_STATUS','PK_USAGE','FK_USAGE_RL','UK_USAGE_RL','CK_USAGE_TIME','IX_RES_MEMBER_TIME','IX_RL_LANE_TIME','IX_RES_STATUS_TIME')) LOOP
  EXECUTE IMMEDIATE 'ALTER INDEX '||DBMS_ASSERT.ENQUOTE_NAME(r.index_name)||' RENAME TO '||DBMS_ASSERT.ENQUOTE_NAME('OLD_'||r.index_name);
 END LOOP;
END;
/
WHENEVER SQLERROR CONTINUE
